export function generateMensApparel(): ProductSeedItem[] {
  return mensData.map((m) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${m.name} là sản phẩm thời trang nam cao cấp từ thương hiệu ${m.brand}. Sản phẩm được may đo tỉ mỉ theo tiêu chuẩn phom dáng người Việt Nam, kết hợp chất liệu vải tuyển chọn cùng kỹ thuật may hoàn thiện cao cấp, đem lại phong thái lịch lãm, tự tin cho phái mạnh trong mọi hoàn cảnh.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${m.brand}
- **Chất liệu vải may:** ${m.mat}
- **Công nghệ dệt & Xử lý bề mặt:** ${m.tech}
- **Phom dáng thiết kế (Fit):** ${m.fit}
- **Hướng dẫn giặt là & Bảo quản:** ${m.care}
- **Kích cỡ đầy đủ (Size chart):** Đầy đủ các size S, M, L, XL, XXL

### 3. Ưu điểm nổi bật
- Giữ form chuẩn mực, tôn dáng bờ vai và khuôn ngực nam tính mà vẫn đảm bảo độ co giãn, thông thoáng cho cả ngày dài hoạt động.
- Sợi vải bền màu, không bị bai dão hay xù lông sau nhiều chu kỳ giặt máy.

### 4. Gợi ý phối đồ
- Dễ dàng kết hợp cùng quần âu công sở, quần jean năng động hoặc khoác ngoài áo blazer lịch lãm.`;

    const variants = m.colors.map((c, idx) => ({
      attributes: { color: c, size: 'L', brand: m.brand },
      price: m.price,
      stock_quantity: 40 + idx * 10
    }));

    return {
      name: m.name,
      categorySlug: 'mens-apparel',
      brand: m.brand,
      price: m.price,
      description: desc,
      images: TECH_IMAGES.mens_clothing,
      variants
    };
  });
}

