export function generateWomensApparel(): ProductSeedItem[] {
  return womensData.map((w) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${w.name} là mẫu trang phục thiết kế nữ cao cấp từ thương hiệu thời trang uy tín ${w.brand}. Với những đường cắt may tôn vinh đường cong cơ thể phái đẹp cùng chất liệu vải thượng hạng, sản phẩm mang lại vẻ ngoài thanh lịch, quyến rũ và khí chất sang trọng trong mọi sự kiện.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${w.brand}
- **Chất liệu vải chính:** ${w.mat}
- **Kiểu dáng & Đường cắt (Cut & Silhouette):** ${w.cut}
- **Kỹ thuật may & Chi tiết đắt giá:** ${w.tech}
- **Bảo quản & Giặt ủi:** ${w.care}
- **Bảng kích cỡ (Size):** S (40-47kg, eo 60-66cm), M (48-54kg, eo 67-72cm), L (55-62kg, eo 73-78cm), XL (63-70kg, eo 79-85cm)

### 3. Ưu điểm nổi bật
- Giấu khuyết điểm vòng eo và bắp tay khéo léo, tôn lên nét duyên dáng tự nhiên và đôi chân thon gọn.
- Vải mềm mát, êm dịu với làn da nhạy cảm, không bị nhăn nhàu khi ngồi làm việc hay di chuyển lâu.

### 4. Ứng dụng & Hoàn cảnh mặc
- Thích hợp diện đi làm văn phòng công sở, họp hội nghị, dự tiệc cưới hỏi, dạ tiệc sang trọng hay hẹn hò dạo phố.`;

    const variants = w.colors.map((c, idx) => ({
      attributes: { color: c, size: 'M', brand: w.brand },
      price: w.price,
      stock_quantity: 35 + idx * 8
    }));

    return {
      name: w.name,
      categorySlug: 'womens-apparel',
      brand: w.brand,
      price: w.price,
      description: desc,
      images: TECH_IMAGES.womens_clothing,
      variants
    };
  });
}

