export function generateBags(): ProductSeedItem[] {
  return bagData.map((b) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${b.name} là sản phẩm túi xách, balo và đồ da cao cấp từ thương hiệu ${b.brand}. Được chế tác từ những chất liệu tuyển chọn bền chắc cùng đường kim mũi chỉ gia cố chắc chắn, sản phẩm vừa là phụ kiện định hình phong cách cá nhân, vừa tối ưu hóa công năng lưu trữ đồ đạc an toàn, tiện lợi trong nhịp sống di động hàng ngày.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${b.brand}
- **Chất liệu gia công chính:** ${b.mat}
- **Khả năng lưu trữ & Phân ngăn:** ${b.cap}
- **Hệ thống dây quai & Đệm trợ lực:** ${b.strap}
- **Phụ kiện kim loại & Khóa an toàn:** ${b.hard}
- **Kích thước đo đạc thực tế:** ${b.size}

### 3. Ưu điểm nổi trội
- Bền bỉ theo thời gian, chống thấm nước và chống mài mòn xuất sắc bảo vệ an toàn cho laptop và đồ công nghệ đắt tiền.
- Thiết kế công thái học thông minh, phân bổ trọng lượng đồng đều lên cơ thể giúp hạn chế mỏi vai và gù lưng.

### 4. Đối tượng sử dụng
- Doanh nhân, dân văn phòng, học sinh sinh viên, người đam mê du lịch dã ngoại hoặc các tín đồ thời trang dạo phố.`;

    const variants = b.colors.map((c, idx) => ({
      attributes: { color: c, brand: b.brand },
      price: b.price,
      stock_quantity: 30 + idx * 5
    }));

    return {
      name: b.name,
      categorySlug: 'bags-wallets',
      brand: b.brand,
      price: b.price,
      description: desc,
      images: TECH_IMAGES.bags,
      variants
    };
  });
}

