export function generateWatchesAndJewelry(): ProductSeedItem[] {
  return watchJewelryData.map((w) => {
    const desc = `### 1. Tổng quan & Định vị sản phẩm
${w.name} là tác phẩm đồng hồ và trang sức cao cấp từ thương hiệu danh tiếng ${w.brand}. Được hoàn thiện từ những kim loại quý, đá quý tự nhiên và bộ máy cơ khí chính xác, sản phẩm là biểu tượng của sự thành đạt, đẳng cấp và giá trị thẩm mỹ trường tồn theo năm tháng.

### 2. Thông số kỹ thuật chi tiết (Technical Specifications)
- **Thương hiệu:** ${w.brand}
- **Bộ máy vận hành / Chất liệu đá chủ:** ${w.move}
- **Chất liệu vỏ máy / Thân trang sức:** ${w.case}
- **Mặt kính bảo vệ / Giác cắt quang học:** ${w.glass}
- **Thiết kế mặt số / Họa tiết chạm khắc:** ${w.dial}
- **Chất liệu dây đeo / Khóa an toàn:** ${w.strap}
- **Mức độ kháng nước & Tiêu chuẩn bảo hành:** ${w.water}

### 3. Giá trị vượt trội
- Bộ máy cơ khí Thụy Sĩ/Nhật Bản vận hành bền bỉ với độ chính xác cao, khả năng chống từ trường và chống sốc tuyệt vời.
- Kỹ nghệ hoàn thiện kim hoàn thủ công tinh xảo, từng góc vát kim cương và thớ đánh bóng sáng bắt trọn ánh nhìn.

### 4. Đối tượng & Hoàn cảnh sử dụng
- Món quà tặng ý nghĩa nhân dịp kỷ niệm, lễ đính hôn, quà tặng đối tác doanh nhân và phụ kiện hoàn hảo cho các bộ trang phục sang trọng.`;

    const variants = w.colors.map((c, idx) => ({
      attributes: { color: c, brand: w.brand },
      price: w.price,
      stock_quantity: 20 + idx * 4
    }));

    return {
      name: w.name,
      categorySlug: 'watches-jewelry',
      brand: w.brand,
      price: w.price,
      description: desc,
      images: TECH_IMAGES.watches_luxury,
      variants
    };
  });
}
